package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.io.JsonFactory;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import com.fasterxml.jackson.core.util.SharedStrings;
import java.io.*;
import java.io.IOException;
import java.io.StringReader;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.when;

public class ReaderBasedJsonParser__parseName_TriageGen2Test {

    private JsonFactory factory;
    private ReaderBasedJsonParser parser;
    private CharsToNameCanonicalizer mockCanonicalizer;
    private JsonParser.SymbolTable mockSymbols;

    private static final int INT_QUOTE = 34; // '"'

    @Before
    public void setUp() throws Exception {
        factory = new JsonFactory();
        mockCanonicalizer = Mockito.mock(CharsToNameCanonicalizer.class);
        mockSymbols = Mockito.mock(JsonParser.SymbolTable.class);

        // Create parser instance via a real StringReader to avoid complex constructor mocking
        // We will use reflection to inject the mock symbols and manipulate internal state
        parser = (ReaderBasedJsonParser) factory.createParser(new StringReader(""));

        // Inject mock symbols via reflection
        Field symbolsField = ReaderBasedJsonParser.class.getDeclaredField("_symbols");
        symbolsField.setAccessible(true);
        symbolsField.set(parser, mockSymbols);

        // Set hash seed to a known value
        Field hashSeedField = ReaderBasedJsonParser.class.getDeclaredField("_hashSeed");
        hashSeedField.setAccessible(true);
        hashSeedField.set(parser, 12345);
    }

    /**
     * Helper to inject internal buffer state via reflection for testing protected/private fields
     */
    private void setParserState(byte[] buffer, int ptr, int end) throws Exception {
        Field bufferField = ReaderBasedJsonParser.class.getDeclaredField("_inputBuffer");
        bufferField.setAccessible(true);
        bufferField.set(parser, buffer);

        Field ptrField = ReaderBasedJsonParser.class.getDeclaredField("_inputPtr");
        ptrField.setAccessible(true);
        ptrField.set(parser, ptr);

        Field endField = ReaderBasedJsonParser.class.getDeclaredField("_inputEnd");
        endField.setAccessible(true);
        endField.set(parser, end);

        // Mocking _icLatin1 which is usually an int array for fast lookup
        Field icLatin1Field = ReaderBasedJsonParser.class.getDeclaredField("_icLatin1");
        icLatin1Field.setAccessible(true);
        int[] icLatin1 = new int[256];
        icLatin1[0] = 1; // dummy non-zero to pass the (codes[ch] != 0) check
        icLatin1[34] = 1; // '"'
        icLatin1[97] = 1; // 'a'
        icLatin1[98] = 1; // 'b'
        icLatin1[99] = 1; // 'c'
        icLatin1Field.set(parser, icLatin1);
    }

    @Test
    public void testParseName_HandleOddName() throws Exception {
        // Scenario: i != INT_QUOTE
        // We need to mock _handleOddName. Since it's protected, we use a spy or a subclass.
        ReaderBasedJsonParser spyParser = Mockito.spy((ReaderBasedJsonParser) factory.createParser(new StringReader("")));
        when(spyParser._handleOddName(99)).thenReturn("oddName");

        Method method = ReaderBasedJsonParser.class.getDeclaredMethod("_parseName", int.class);
        method.setAccessible(true);

        String result = (String) method.invoke(spyParser, 99);
        Assert.assertEquals("oddName", result);
    }

    @Test
    public void testParseName_SimpleNameWithQuote() throws Exception {
        // Scenario: i == INT_QUOTE, ptr < inputLen, finds '"'
        // Input: "abc"
        byte[] buffer = new byte[] { '"', 'a', 'b', 'c', '"' };
        setParserState(buffer, 0, 5);

        when(mockSymbols.findSymbol(any(), any(byte[].class), anyInt(), anyInt())).thenReturn("abc");

        Method method = ReaderBasedJsonParser.class.getDeclaredMethod("_parseName", int.class);
        method.setAccessible(true);

        String result = (String) method.invoke(parser, INT_QUOTE);

        Assert.assertEquals("abc", result);

        Field ptrField = ReaderBasedJsonParser.class.getDeclaredField("_inputPtr");
        ptrField.setAccessible(true);
        Assert.assertEquals(1, ptrField.get(parser)); // ptr+1 after quote skip
    }

    @Test
    public void testParseName_ComplexNameTriggersParseName2() throws Exception {
        // Scenario: i == INT_QUOTE, ptr < inputLen, but loop breaks or ends without finding '"'
        // This forces the code to fall through to _parseName2
        // We use a character that isn't in our dummy _icLatin1 or isn't '"'
        byte[] buffer = new byte[] { 'x', 'y', 'z' }; 
        setParserState(buffer, 0, 3);

        // We need to mock _parseName2. Since we can't mock final/internal easily without PowerMock,
        // we rely on the fact that _parseName2 is called. 
        // However, we can test the logic flow by ensuring it doesn't crash and reaches the end.
        // To properly test the branch, we look at the state change.

        Method method = ReaderBasedJsonParser.class.getDeclaredMethod("_parseName", int.class);
        method.setAccessible(true);

        try {
            method.invoke(parser, INT_QUOTE);
        } catch (Exception e) {
            // Expected to fail eventually because _parseName2 is called on a real object 
            // but it verifies the branch was reached.
        }

        Field ptrField = ReaderBasedJsonParser.class.getDeclaredField("_inputPtr");
        ptrField.setAccessible(true);
        Assert.assertEquals(3, ptrField.get(parser)); // ptr was incremented to inputLen
    }

    @Test
    public void testParseName_EmptyBuffer() throws Exception {
        // Scenario: ptr >= inputLen
        setParserState(new byte[0], 0, 0);

        Method method = ReaderBasedJsonParser.class.getDeclaredMethod("_parseName", int.class);
        method.setAccessible(true);

        try {
            method.invoke(parser, INT_QUOTE);
        } catch (Exception e) {
            // Fallthrough to _parseName2
        }

        Field ptrField = ReaderBasedJsonParser.class.getDeclaredField("_inputPtr");
        ptrField.setAccessible(true);
        Assert.assertEquals(0, ptrField.get(parser));
    }

    @Test
    public void testParseName_LoopBreakWithoutQuote() throws Exception {
        // Scenario: ch < maxCode and codes[ch] != 0 is true, but ch != '"'
        // This triggers the 'break' in the do-while loop.
        byte[] buffer = new byte[] { 'a' }; 
        setParserState(buffer, 0, 1);

        Method method = ReaderBasedJsonParser.class.getDeclaredMethod("_parseName", int.class);
        method.setAccessible(true);

        try {
            method.invoke(parser, INT_QUOTE);
        } catch (Exception e) {
            // Fallthrough to _parseName2
        }

        Field ptrField = ReaderBasedJsonParser.class.getDeclaredField("_inputPtr");
        ptrField.setAccessible(true);
        Assert.assertEquals(1, ptrField.get(parser)); // ptr incremented once then broke
    }
}
